const i=document.querySelectorAll("[data-registration-form]");i.forEach(e=>{const t=e.querySelector("[data-status]");e.addEventListener("submit",async n=>{n.preventDefault();const r=new FormData(e),o=r.get("studentType"),c=e.querySelector('[name="studentDocuments"]');if(o==="new"&&c.files.length!==4){t.textContent="Select all four required documents together.",t.classList.remove("success"),t.classList.add("error");return}t.textContent="Submitting...",t.classList.remove("success","error");try{const s=await fetch("http://localhost:5000/api/register",{method:"POST",body:r}),a=await s.json();if(!s.ok)throw new Error(a.message||"Registration failed.");t.textContent=a.message,t.classList.add("success"),e.reset()}catch(s){t.textContent=s.message,t.classList.add("error")}})});
